+var unescapeMap = [256]byte{
+	'"':  '"',
+	'\\': '\\',
+	'/':  '/',
+	'b':  '\b',
+	'f':  '\f',
+	'n':  '\n',
+	'r':  '\r',
+	't':  '\t',
+}
+
+func unescapeStringOptimized(buf []byte) []byte {
+	cursor := 0
+	bufLen := len(buf)
+	for cursor < bufLen {
+		idx := bytes.IndexByte(buf[cursor:], '\\')
+		if idx == -1 {
+			return buf
+		}
+		cursor += idx + 1
+		if cursor >= bufLen {
+			return buf
+		}
+		c := buf[cursor]
+		if c == 'u' {
+			code := unicodeToRune(buf[cursor+1 : cursor+5])
+			unicode := []byte(string(code))
+			buf = append(append(buf[:cursor-1], unicode...), buf[cursor+5:]...)
+			bufLen = len(buf)
+			cursor += len(unicode) - 1 // -1 because we will cursor++
+		} else {
+			buf[cursor] = unescapeMap[c]
+			buf = append(buf[:cursor-1], buf[cursor:]...)
+			bufLen = len(buf)
+			cursor--
+		}
+		cursor++
+	}
+	return buf
+}

